package com.calimero.mero.invite

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Web invitations: tokens generated by the web apps' own code (`bs58` + `fflate`
 * `deflateSync(…, { level: 9 })`, as in apps/mero-design/app/src/utils/invitation.ts
 * `encodeInvitationObject`). (Swift `AppInvitationTests`, same vectors.)
 */
class AppInvitationTest {
    private val namespaceId = (1..32).joinToString("") { "%02x".format(it) }

    @Test
    fun `decodes mero-design's token`() {
        val decoded = AppInvitation.decode(DESIGN_TOKEN)!!
        assertEquals("Design Team ✨", decoded.name)
        assertEquals(namespaceId, decoded.namespaceId)
        assertEquals("cd".repeat(64), decoded.invitation.inviterSignature)
        assertEquals(4_102_444_800L, decoded.invitation.invitation.expirationTimestamp)
        assertEquals(listOf("ab".repeat(32)), decoded.invitation.invitation.admitters)
        assertEquals(List(32) { 3 }, decoded.invitation.applicationId)
    }

    @Test
    fun `decodes mero-chat's token from a link`() {
        val link = InviteLink.invitation(CHAT_TOKEN, "com.calimero.chat")
        val decoded = AppInvitation.parse(link, expectedSlug = "com.calimero.chat")!!
        assertEquals("general", decoded.name)
        assertEquals(namespaceId, decoded.namespaceId)
    }

    @Test
    fun `refuses another app's link`() {
        val link = InviteLink.invitation(CHAT_TOKEN, "com.calimero.chat")
        assertNull(AppInvitation.parse(link, expectedSlug = "com.calimero.mero-design"))
        assertNotNull("a bare token", AppInvitation.parse(CHAT_TOKEN, expectedSlug = "com.calimero.mero-design"))
    }

    @Test
    fun `round-trips under the chosen name key`() {
        val original = AppInvitation.decode(DESIGN_TOKEN)!!
        val renamed = AppInvitation(original.invitation, "Ops")
        val token = renamed.token(nameKey = "__teamName")
        val json = InviteCodec.decode(token)!!
        assertTrue(json, json.contains(""""__teamName":"Ops""""))
        val back = AppInvitation.decode(token)!!
        assertEquals(renamed, back)
        assertEquals(namespaceId, back.namespaceId)
        // The signed envelope re-encodes verbatim.
        assertEquals(original.invitation, back.invitation)

        val link = renamed.link("com.calimero.mero-design")
        assertEquals("Ops", AppInvitation.parse(link, "com.calimero.mero-design")?.name)
    }

    @Test
    fun `takes a bare camelCase invitation in a data envelope`() {
        val group = (1..32).joinToString(",")
        val json =
            """{"data":{"invitation":{"inviter_identity":[],"group_id":[$group],"expiration_timestamp":1,""" +
                """"secret_salt":[]},"inviterSignature":"ff"}}"""
        val decoded = AppInvitation.decodeJson(json)!!
        assertNull(decoded.name)
        assertEquals("ff", decoded.invitation.inviterSignature)
        assertEquals(namespaceId, decoded.namespaceId)
    }

    @Test
    fun `reads the kotlin sample's space name`() {
        val signed = AppInvitation.decode(DESIGN_TOKEN)!!.invitation
        assertEquals("Lab", AppInvitation.decodeJson("""{"spaceName":"Lab","invitation":${signed.raw}}""")?.name)
    }

    @Test
    fun `refuses what is not an invitation`() {
        assertNull(AppInvitation.decode("not a token"))
        assertNull(AppInvitation.decodeJson("""{"invitation":{"group_id":[1]}}"""))
        assertNull(AppInvitation.parse(""))
    }

    private companion object {
        /** `{ invitation: <signed>, __teamName: "Design Team ✨" }`: mero-design's payload. */
        const val DESIGN_TOKEN =
            "2GwyBbBnCnvyRuScxi99tFjch1PVttFHKohW3h5opAJoVRsfDfL1p8kqtQpsQuXv49V3j4QxzgKFAA3MeQHGYaSy2babRoM8VdPV5cQHqGkk" +
                "oHbvXgftBUc6GEVFTffVJvJfYtMgR36iLrsgbwm4mnzwSZd9kbT1MwxoU3WTo6Ce7qGMdMMfLa7ramXMGGWrey1r88QgqtMoWWqVaVLRMGHeN" +
                "m6bEfaNpnYJpLgR4FvEyxNB121xoFo1iA9BSTmUJ1bm5rWgkhXLZjCdT54gnuz7VsthCZmRLSs6hXch6f3C7Gf36ayFmAcuaAVqfu5vqo6a9X" +
                "vWmU"

        /** `{ invitation: <signed>, groupAlias: "general" }`: mero-chat's payload. */
        const val CHAT_TOKEN =
            "3LgQqvPGuP2Ea6P5dcV7FRXcfnrVPeQKJ5pJBrQQEUvLeg8RBjT7Nw6cNbxyhhLvvHdT5mrocMJXDzLiVUC22kd4v8rT6vxD6m7bSAwpJ7kn" +
                "qns4Ac2i6Nqt5mXQJrFwywC5gqUf8mHSX6xriR3kCpotoN8MKybA92LmAeCHqWcojqXDyMYMubfzzet91stoJR2RdGs5zRZeK9BTVKyCpaKPQ" +
                "3ZBGxBGVRGGB1e8zB63zkgeX7mpFTAP6JRp76tQ6Yekk1d9HR7AWF2PJDBtgtumpxRcpuqJ9AabDMwXujTG7Kzh2bM4"
    }
}
